import React, { useState, useEffect, useRef } from 'react';
import { BrowserRouter as Router, Routes, Route, Link, useNavigate, useLocation } from 'react-router-dom';
import { 
  Calendar, Scan, Bell, ChevronLeft, 
  Zap, Image as ImageIcon, Bot, Mic, Send, X 
} from 'lucide-react';
import MeetingRoom from './MeetingRoom';
import Transport from './Transport';
import './App.css';

// --- 新增：ChatBot 组件 ---
const ChatBot = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState([
    { id: 1, type: 'bot', text: 'Hi! I am your assistant. How can I help you today?' }
  ]);
  const [inputValue, setInputValue] = useState('');
  const [isListening, setIsListening] = useState(false);

  // 拖拽位置状态 (默认右下角)
  const [position, setPosition] = useState({ x: window.innerWidth - 80, y: window.innerHeight - 150 });
  const [isDragging, setIsDragging] = useState(false);
  const dragRef = useRef(null);

  // 处理拖拽开始
  const handleDragStart = (e) => {
    setIsDragging(true);
    dragRef.current = {
      offsetX: (e.clientX || e.touches[0].clientX) - position.x,
      offsetY: (e.clientY || e.touches[0].clientY) - position.y
    };
  };

  // 处理拖拽过程
  const handleDrag = (e) => {
    if (!isDragging) return;
    const clientX = e.clientX || (e.touches && e.touches[0].clientX);
    const clientY = e.clientY || (e.touches && e.touches[0].clientY);

    // 限制在屏幕范围内
    const newX = Math.min(Math.max(0, clientX - dragRef.current.offsetX), window.innerWidth - 60);
    const newY = Math.min(Math.max(0, clientY - dragRef.current.offsetY), window.innerHeight - 60);

    setPosition({ x: newX, y: newY });
  };

  const handleDragEnd = () => {
    setTimeout(() => setIsDragging(false), 50); // 延迟以区分点击和拖拽
  };

  // 模拟发送消息
  const handleSend = (text) => {
    const msg = text || inputValue;
    if (!msg.trim()) return;

    const newMessages = [...messages, { id: Date.now(), type: 'user', text: msg }];
    setMessages(newMessages);
    setInputValue('');

    // 模拟机器人回复逻辑
    setTimeout(() => {
      let botReply = "I'm not sure how to help with that. Try asking to book a room!";
      if (msg.toLowerCase().includes('book') && msg.toLowerCase().includes('room')) {
        botReply = "Certainly! I've found a slot. Idea Lab 6 on 2026-02-12 at 11:00 AM for 5 participants. Should I confirm?";
      } else if (msg.toLowerCase().includes('yes') || msg.toLowerCase().includes('confirm')) {
        botReply = "Booking complete! You can find the details in your Meeting Room list. ✅";
      }

      setMessages(prev => [...prev, { id: Date.now() + 1, type: 'bot', text: botReply }]);
    }, 1000);
  };

  // 模拟语音识别
  const toggleListening = () => {
    setIsListening(true);
    setTimeout(() => {
      setIsListening(false);
      const speechText = "Please help me book a meeting room tomorrow for 5 people";
      setInputValue(speechText);
      handleSend(speechText);
    }, 2000);
  };

  return (
    <>
      {/* 悬浮按钮 */}
      <div 
        className="chatbot-float-btn"
        style={{ left: `${position.x}px`, top: `${position.y}px` }}
        onMouseDown={handleDragStart}
        onMouseMove={handleDrag}
        onMouseUp={handleDragEnd}
        onTouchStart={handleDragStart}
        onTouchMove={handleDrag}
        onTouchEnd={handleDragEnd}
        onClick={() => { if (!isDragging) setIsOpen(!isOpen); }}
      >
        <Bot size={28} />
        <span>Chat with us</span>
      </div>

      {/* 聊天窗口 */}
      {isOpen && (
        <div className="chat-window-overlay">
          <div className="chat-header">
            <div style={{display:'flex', alignItems:'center', gap: '8px'}}>
              <Bot size={20} />
              <span style={{fontWeight:'bold'}}>Smart Assistant</span>
            </div>
            <X size={20} onClick={() => setIsOpen(false)} style={{cursor:'pointer'}} />
          </div>

          <div className="chat-messages">
            {messages.map(m => (
              <div key={m.id} className={`message ${m.type}`}>{m.text}</div>
            ))}
          </div>

          <div className="chat-input-area">
            <button className={`mic-btn ${isListening ? 'listening' : ''}`} onClick={toggleListening}>
              <Mic size={20} />
            </button>
            <input 
              type="text" 
              placeholder="Type a message..." 
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            />
            <button className="send-btn" onClick={() => handleSend()}>
              <Send size={20} />
            </button>
          </div>
        </div>
      )}
    </>
  );
};

// --- 以下是你原本的 ScanPage, Home, App 组件 (保持不变，只需在 App 内部加入 <ChatBot />) ---

const ScanPage = () => { /* 保持原样 */ };
const Home = () => { /* 保持原样 */ };

function App() {
  return (
    <Router>
      <div className="mobile-app">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/meeting-room" element={<MeetingRoom />} />
          <Route path="/transport" element={<Transport />} />
          <Route path="/scan" element={<ScanPage />} />
        </Routes>
        <FooterWithConditionalRendering />

        {/* 在这里加入 ChatBot，它将显示在所有页面中 */}
        <ChatBot />
      </div>
    </Router>
  );
}

const FooterWithConditionalRendering = () => {
  const location = useLocation();
  if (location.pathname === '/scan') return null;
  return (
    <footer className="bottom-nav">
      <Link to="/" className={`nav-item ${location.pathname === '/' ? 'active' : ''}`}><img src="/icon_img/home.png" alt="H" /><span>Home</span></Link>
      <div className="nav-item"><img src="/icon_img/dashboard.png" alt="D" /><span>Dashboard</span></div>
      <div className="nav-item"><img src="/icon_img/info.png" alt="I" /><span>Info</span></div>
      <div className="nav-item"><img src="/icon_img/profile.png" alt="P" /><span>Profile</span></div>
    </footer>
  );
};

export default App;
